CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Categories" (
    "CategoryID" integer GENERATED BY DEFAULT AS IDENTITY,
    "CategoryName" character varying(100) NOT NULL,
    CONSTRAINT "PK_Categories" PRIMARY KEY ("CategoryID")
);

CREATE TABLE "Roles" (
    "RoleID" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoleName" character varying(30) NOT NULL,
    CONSTRAINT "PK_Roles" PRIMARY KEY ("RoleID")
);

CREATE TABLE "Toppings" (
    "ToppingID" integer GENERATED BY DEFAULT AS IDENTITY,
    "ToppingName" character varying(100) NOT NULL,
    "Price" numeric(18,2) NOT NULL,
    "IsAvailable" boolean NOT NULL DEFAULT TRUE,
    CONSTRAINT "PK_Toppings" PRIMARY KEY ("ToppingID"),
    CONSTRAINT "CK_Toppings_Price" CHECK ("Price" >= 0)
);

CREATE TABLE "Vouchers" (
    "VoucherID" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" character varying(50) NOT NULL,
    "DiscountValue" numeric(18,2) NOT NULL,
    "MinOrderValue" numeric(18,2) NOT NULL,
    "MaxDiscountAmount" numeric(18,2) NOT NULL,
    "Quantity" integer NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "ExpiryDate" timestamp with time zone NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_Vouchers" PRIMARY KEY ("VoucherID"),
    CONSTRAINT "CK_Vouchers_DiscountValue" CHECK ("DiscountValue" > 0),
    CONSTRAINT "CK_Vouchers_MaxDiscountAmount" CHECK ("MaxDiscountAmount" >= 0),
    CONSTRAINT "CK_Vouchers_MinOrderValue" CHECK ("MinOrderValue" >= 0),
    CONSTRAINT "CK_Vouchers_Quantity" CHECK ("Quantity" >= 0)
);

CREATE TABLE "Products" (
    "ProductID" integer GENERATED BY DEFAULT AS IDENTITY,
    "CategoryID" integer NOT NULL,
    "ProductName" character varying(100) NOT NULL,
    "Price" numeric(18,2) NOT NULL,
    "ImageURL" character varying(500),
    "IsAvailable" boolean NOT NULL DEFAULT TRUE,
    CONSTRAINT "PK_Products" PRIMARY KEY ("ProductID"),
    CONSTRAINT "CK_Products_Price" CHECK ("Price" >= 0),
    CONSTRAINT "FK_Products_Categories_CategoryID" FOREIGN KEY ("CategoryID") REFERENCES "Categories" ("CategoryID") ON DELETE RESTRICT
);

CREATE TABLE "Users" (
    "UserID" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoleID" integer NOT NULL,
    "FullName" character varying(100) NOT NULL,
    "Phone" character varying(15) NOT NULL,
    "Email" character varying(150) NOT NULL,
    "PasswordHash" character varying(255) NOT NULL,
    "Status" character varying(30) NOT NULL DEFAULT 'Active',
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_Users" PRIMARY KEY ("UserID"),
    CONSTRAINT "FK_Users_Roles_RoleID" FOREIGN KEY ("RoleID") REFERENCES "Roles" ("RoleID") ON DELETE RESTRICT
);

CREATE TABLE "Orders" (
    "OrderID" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserID" integer NOT NULL,
    "VoucherID" integer,
    "OrderType" character varying(30) NOT NULL,
    "TotalAmount" numeric(18,2) NOT NULL,
    "DiscountAmount" numeric(18,2) NOT NULL,
    "FinalAmount" numeric(18,2) NOT NULL,
    "PaymentMethod" character varying(30) NOT NULL,
    "Status" character varying(30) NOT NULL DEFAULT 'Pending',
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_Orders" PRIMARY KEY ("OrderID"),
    CONSTRAINT "CK_Orders_Amounts" CHECK ("TotalAmount" >= 0 AND "DiscountAmount" >= 0 AND "FinalAmount" = "TotalAmount" - "DiscountAmount" AND "FinalAmount" >= 0),
    CONSTRAINT "FK_Orders_Users_UserID" FOREIGN KEY ("UserID") REFERENCES "Users" ("UserID") ON DELETE RESTRICT,
    CONSTRAINT "FK_Orders_Vouchers_VoucherID" FOREIGN KEY ("VoucherID") REFERENCES "Vouchers" ("VoucherID") ON DELETE RESTRICT
);

CREATE TABLE "Feedbacks" (
    "FeedbackID" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserID" integer NOT NULL,
    "OrderID" integer NOT NULL,
    "ProductID" integer NOT NULL,
    "Rating" integer NOT NULL,
    "Comment" character varying(500),
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (NOW()),
    CONSTRAINT "PK_Feedbacks" PRIMARY KEY ("FeedbackID"),
    CONSTRAINT "CK_Feedbacks_Rating" CHECK ("Rating" BETWEEN 1 AND 5),
    CONSTRAINT "FK_Feedbacks_Orders_OrderID" FOREIGN KEY ("OrderID") REFERENCES "Orders" ("OrderID") ON DELETE CASCADE,
    CONSTRAINT "FK_Feedbacks_Products_ProductID" FOREIGN KEY ("ProductID") REFERENCES "Products" ("ProductID") ON DELETE RESTRICT,
    CONSTRAINT "FK_Feedbacks_Users_UserID" FOREIGN KEY ("UserID") REFERENCES "Users" ("UserID") ON DELETE RESTRICT
);

CREATE TABLE "OrderDetails" (
    "OrderDetailID" integer GENERATED BY DEFAULT AS IDENTITY,
    "OrderID" integer NOT NULL,
    "ProductID" integer NOT NULL,
    "Quantity" integer NOT NULL,
    "Size" character varying(30) NOT NULL,
    "SugarLevel" character varying(30) NOT NULL,
    "IceLevel" character varying(30) NOT NULL,
    "Note" character varying(500),
    "UnitPrice" numeric(18,2) NOT NULL,
    CONSTRAINT "PK_OrderDetails" PRIMARY KEY ("OrderDetailID"),
    CONSTRAINT "CK_OrderDetails_Quantity" CHECK ("Quantity" > 0),
    CONSTRAINT "CK_OrderDetails_UnitPrice" CHECK ("UnitPrice" >= 0),
    CONSTRAINT "FK_OrderDetails_Orders_OrderID" FOREIGN KEY ("OrderID") REFERENCES "Orders" ("OrderID") ON DELETE CASCADE,
    CONSTRAINT "FK_OrderDetails_Products_ProductID" FOREIGN KEY ("ProductID") REFERENCES "Products" ("ProductID") ON DELETE RESTRICT
);

CREATE TABLE "OrderDetailToppings" (
    "ID" integer GENERATED BY DEFAULT AS IDENTITY,
    "OrderDetailID" integer NOT NULL,
    "ToppingID" integer NOT NULL,
    "Price" numeric(18,2) NOT NULL,
    CONSTRAINT "PK_OrderDetailToppings" PRIMARY KEY ("ID"),
    CONSTRAINT "CK_OrderDetailToppings_Price" CHECK ("Price" >= 0),
    CONSTRAINT "FK_OrderDetailToppings_OrderDetails_OrderDetailID" FOREIGN KEY ("OrderDetailID") REFERENCES "OrderDetails" ("OrderDetailID") ON DELETE CASCADE,
    CONSTRAINT "FK_OrderDetailToppings_Toppings_ToppingID" FOREIGN KEY ("ToppingID") REFERENCES "Toppings" ("ToppingID") ON DELETE RESTRICT
);

INSERT INTO "Roles" ("RoleID", "RoleName")
VALUES (1, 'Customer');
INSERT INTO "Roles" ("RoleID", "RoleName")
VALUES (2, 'Admin');

CREATE UNIQUE INDEX "IX_Categories_CategoryName" ON "Categories" ("CategoryName");

CREATE UNIQUE INDEX "IX_Feedbacks_OrderID_ProductID" ON "Feedbacks" ("OrderID", "ProductID");

CREATE INDEX "IX_Feedbacks_ProductID" ON "Feedbacks" ("ProductID");

CREATE INDEX "IX_Feedbacks_UserID" ON "Feedbacks" ("UserID");

CREATE INDEX "IX_OrderDetails_OrderID" ON "OrderDetails" ("OrderID");

CREATE INDEX "IX_OrderDetails_ProductID" ON "OrderDetails" ("ProductID");

CREATE UNIQUE INDEX "IX_OrderDetailToppings_OrderDetailID_ToppingID" ON "OrderDetailToppings" ("OrderDetailID", "ToppingID");

CREATE INDEX "IX_OrderDetailToppings_ToppingID" ON "OrderDetailToppings" ("ToppingID");

CREATE INDEX "IX_Orders_Status" ON "Orders" ("Status");

CREATE INDEX "IX_Orders_UserID_CreatedAt" ON "Orders" ("UserID", "CreatedAt");

CREATE INDEX "IX_Orders_VoucherID" ON "Orders" ("VoucherID");

CREATE UNIQUE INDEX "IX_Products_CategoryID_ProductName" ON "Products" ("CategoryID", "ProductName");

CREATE UNIQUE INDEX "IX_Roles_RoleName" ON "Roles" ("RoleName");

CREATE UNIQUE INDEX "IX_Toppings_ToppingName" ON "Toppings" ("ToppingName");

CREATE UNIQUE INDEX "IX_Users_Email" ON "Users" ("Email");

CREATE UNIQUE INDEX "IX_Users_Phone" ON "Users" ("Phone");

CREATE INDEX "IX_Users_RoleID" ON "Users" ("RoleID");

CREATE UNIQUE INDEX "IX_Vouchers_Code" ON "Vouchers" ("Code");

SELECT setval(
    pg_get_serial_sequence('"Roles"', 'RoleID'),
    GREATEST(
        (SELECT MAX("RoleID") FROM "Roles") + 1,
        nextval(pg_get_serial_sequence('"Roles"', 'RoleID'))),
    false);

